source("pre.R")
con <- duck()
q <- function(s) tryCatch(DBI::dbGetQuery(con, s)[[1]], error = function(e) paste("ERR", substr(conditionMessage(e),1,90)))
x <- decimal128(c("1.25","-1.25","99.99", NA), 5, 2)
P(c(x, x)); P(c(x, 1L)); P(c(1L, x)); P(c(x, NA)); P(c(x, NULL)); P(c(x, "3.14159")); P(c(x, "abc")); P(c(x, 1.5)); P(c(x, 2)); P(c(x, 2^40)); P(c(x, TRUE)); P(c(x, int64(5))); P(c(int64(5), x)); P(c(x, uint128("340282366920938463463374607431768211454"))); P(c(x, factor("a"))); P(c(x, list(1))); P(c(x, Sys.Date())); P(c(x, bit64::as.integer64(7))); P(c(bit64::as.integer64(7), x))
P(c(a = x[1], b = x[2])); P(c(a = x[1:2])); P(c(setNames(x[1:2], c("p","p")), z = 1L)); P(c(x, use.names = FALSE)); P(c(setNames(x[1:2], c("p","q")), use.names = FALSE)); P(c(x[1], recursive = TRUE)); P(c(x[1], use.names = 5L)); P(c(use = x[1])); P(c(x[1], rec=2L))
P(c(decimal128("1.5", 38, 1), decimal128("0.12345", 10, 5))); cat(q("SELECT typeof([1.5::DECIMAL(38,1), 0.12345::DECIMAL(10,5)])"), "\n")
P(c(decimal128("1.5", 30, 1), decimal128("0.12345", 10, 5), 5L, int64(1))); cat(q("SELECT typeof([1.5::DECIMAL(30,1), 0.12345::DECIMAL(10,5), 5::INTEGER, 1::BIGINT])"), "\n")
P(c(decimal128("1.5", 5, 5-4), int128(1))); cat(q("SELECT typeof([1.5::DECIMAL(5,1), 1::HUGEINT])"), "\n")
P(c(decimal128("0.5", 38, 38), 1L)); cat(q("SELECT typeof([0.5::DECIMAL(38,38), 1::INTEGER])"), q("SELECT [0.5::DECIMAL(38,38), 1::INTEGER]::VARCHAR"), "\n")
P(c(decimal128("0.5", 38, 38), decimal128("1",1,0))); cat(q("SELECT typeof([0.5::DECIMAL(38,38), 1::DECIMAL(1,0)])"), "\n")
P(c(decimal128("5", 20, 0), 1L, decimal128("0.5", 38, 30))); cat(q("SELECT typeof([5::DECIMAL(20,0), 1::INTEGER, 0.5::DECIMAL(38,30)])"), "\n")
P(c(decimal128("0.5", 38, 30), 1L, decimal128("5", 20, 0)));  cat(q("SELECT typeof([0.5::DECIMAL(38,30), 1::INTEGER, 5::DECIMAL(20,0)])"), "\n")
P(c(1L, decimal128("0.5", 5, 4), int64(1), decimal128("5", 30, 0)));  cat(q("SELECT typeof([1::INTEGER, 0.5::DECIMAL(5,4), 1::BIGINT, 5::DECIMAL(30,0)])"), "\n")
P(c(decimal128("0.5", 38, 20), int64(3), decimal128("0.5", 25, 25)));  cat(q("SELECT typeof([0.5::DECIMAL(38,20), 3::BIGINT, 0.5::DECIMAL(25,25)])"), "\n")
P(c(decimal128("0.5", 25, 25), int64(3), decimal128("0.5", 38, 20)));  cat(q("SELECT typeof([0.5::DECIMAL(25,25), 3::BIGINT, 0.5::DECIMAL(38,20)])"), "\n")
# assignment
y <- x; P({y[1] <- 5L; y}); P({y[2] <- "7.777"; y}); P({y[2] <- 7.5; y}); P({y[2] <- 7; y}); P({y[2] <- decimal128("7.777", 5, 3); y}); P({y[2] <- decimal128("7.770", 5, 3); y}); P({y[2] <- 1000L; y}); P({y[7] <- 1L; y}); P({y[[1]] <- NA; y}); P({y[1] <- NULL; y}); P({y[1:2] <- c(1L,2L,3L); y}); P({y[c(TRUE,FALSE)] <- 0L; y}); P({y["nm"] <- 3L; y}); P({y[[2]] <- int64(4); y}); P({y[-1] <- 9L; y}); P({y[NA] <- 9L; y}); P({y[0] <- 9L; y}); P({y[2] <- list(1); y}); P({y[2] <- factor("1"); y}); P({y[2] <- "x"; y}); P({y[2] <- NA_character_; y}); P({y[1.9] <- 3L; y})
y <- x; P({is.na(y) <- 1; y}); P({length(y) <- 6; y}); P({length(y) <- 2; y}); P({names(y) <- c("a","b"); y}); P(y["a"]); P(y[["b"]]); P(y["zz"]); P(y[5]); P(y[c("a","a")]); P({y[["a"]] <- 3L; y}); P({levels(y) <- "a"; y}); P({attr(y, "scale") <- 0L; y}); P({dim(y) <- c(1,2); y})
z <- setNames(x, c("ab","ab","","abc")); P(z["ab"]); P(z[["ab"]]); P(z[["a", exact=FALSE]]); P(z[""]); P(z$ab); P(z[["zz"]]); P(z[[5]]); P(z[[NA]]); P(z[[1:2]])
P(rep(x, 2)); P(rep(x, each=2, times=1)); P(rep(z, length.out=5)); P(rep_len(x, 6)); P(rev(z)); P(head(x, 2)); P(tail(x, 1)); P(x[-1]); P(x[x > 0L]); P(x[c(TRUE, NA)]); P(append(x, 1L, 1)); P(split(x, c(1,1,2,2))); P(ifelse(c(TRUE,FALSE,TRUE,NA), x, x)); P(replace(x, 1, 3L)); P(which(x > 1L)); P(which.max(x)); P(vapply(x, function(v) as.character(v), "")); P(sapply(x, function(v) v)); P(lapply(x[1], function(v) v)); P(mapply(function(a) a, x)); P(Reduce(`+`, x[1:3])); P(do.call(c, as.list(x))); P(outer(x[1:2], x[1:2])); P(x %*% x); P(seq_along(x)); P(setdiff(x, x[1])); P(union(x[1], x[2])); P(intersect(x, x[3:4])); P(rowsum(x, c(1,1,2,2)));P(cut(x, 2)); P(tapply(x, c(1,1,2,2), sum)); P(aggregate(x ~ g, data.frame(x = x, g = c(1,1,2,2)), sum)); P(merge(data.frame(k = x), data.frame(k = decimal128("1.250", 6, 3), v = 1)))
